# Minimal VT100/ANSI parser rendering an 80x24 screen (public-domain concept)
import re

class Screen:
    def __init__(self, w=80, h=24):
        self.w, self.h = w, h
        self.buf = [[" "] * w for _ in range(h)]
        self.r, self.c = 0, 0
    def put(self, ch):
        if ch == "\n":
            self.r = min(self.h - 1, self.r + 1); self.c = 0; return
        self.buf[self.r][self.c] = ch
        self.c += 1
        if self.c >= self.w: self.c = 0; self.r = min(self.h - 1, self.r + 1)
    def csi(self, params, cmd):
        p = [int(x) if x else 1 for x in params.split(";")] if params else [1]
        n = p[0]
        if cmd == "A": self.r = max(0, self.r - n)
        elif cmd == "B": self.r = min(self.h - 1, self.r + n)
        elif cmd == "C": self.c = min(self.w - 1, self.c + n)
        elif cmd == "D": self.c = max(0, self.c - n)
        elif cmd == "H":
            self.r = min(self.h - 1, (p[0] if len(p) > 0 else 1) - 1)
            self.c = min(self.w - 1, (p[1] if len(p) > 1 else 1) - 1)
        elif cmd == "J" and n == 2:
            self.buf = [[" "] * self.w for _ in range(self.h)]
        elif cmd == "K":
            self.buf[self.r][self.c:] = [" "] * (self.w - self.c)
    def render(self):
        return "\n".join("".join(row).rstrip() for row in self.buf).rstrip("\n")

def vt100(stream):
    s, i, out = Screen(), 0, ""
    while i < len(stream):
        ch = stream[i]
        if ch == "\x1b" and i + 1 < len(stream) and stream[i+1] == "[":
            m = re.match(r"\[([0-9;]*)([A-Za-z])", stream[i+1:])
            s.csi(m.group(1), m.group(2)); i += 1 + m.end()
        else:
            s.put(ch); i += 1
    return s.render()

